(()=>{const art={"clap":"data:image/webp;base64,","step":"data:image/webp;base64,","tap":"data:image/webp;base64,"};for(const name of ["patterning-pdf","pattern-resources"]){let h=ML_ENGINES[name];if(!h||h.includes("const mlActionPictures="))continue;h=h.replace("function show(value,kind){","const mlActionPictures="+JSON.stringify(art)+";function show(value,kind){const picture=mlActionPictures[String(value).toLowerCase()];if(picture)return '<span class=\"symbol action-picture\"><img src=\"'+picture+'\" alt=\"\" draggable=\"false\"><b>'+esc(value)+'</b></span>';");h=h.replace("</head>","<style>"+".action-picture{display:flex!important;flex-direction:column!important;align-items:center;justify-content:center;min-height:0;width:100%;height:100%;gap:3px}.action-picture img{flex:1;min-height:0;height:0;width:100%;object-fit:contain;pointer-events:none}.action-picture b{font-size:clamp(14px,1.4vw,22px);line-height:1.05;flex:none}"+"</style></head>");ML_ENGINES[name]=h}window.ML_ACTION_PICTURES=art;})();
